/// <summary>
/// AVADAIOrderAccount
/// </summary>
/// <returns>CustAccount</returns>
display Boolean AVADAIisProforma()
{
    boolean         ret;
    CustInvoiceJour custInvoiceJour;

    custInvoiceJour = custInvoiceJour::findRecId(this.JournalRecId);

    if(custInvoiceJour.recid)
    {
        ret = custInvoiceJour.Proforma;
    }
    else
    {
        ret = true;
    }

    return ret;
}

/// <summary>
/// AVADAIOrderAccount
/// </summary>
/// <returns>CustAccount</returns>
display InvoiceId AVADAIInvoiceId()
{
    CustInvoiceJour     custInvoiceJour;

    custInvoiceJour     =   CustInvoiceJour::findRecId(this.JournalRecId);

    return custInvoiceJour.InvoiceId;
}

/// <summary>
/// AVADAIInvoiceAccountAndId
/// </summary>
/// <returns>InvoiceAccount and InvoiceId</returns>
display AVADAIRefNum AVADAIInvoiceAccountAndId()
{
    CustInvoiceJour     custInvoiceJour;

    custInvoiceJour     =   CustInvoiceJour::findRecId(this.JournalRecId);

    return custInvoiceJour.InvoiceAccount + '_' + custInvoiceJour.InvoiceId;
}

/// <summary>
/// AVADAIDeliveryStreet
/// </summary>
/// <returns>CustAccount</returns>
display LogisticsAddressStreet AVADAIInvoiceStreet()
{
    CustInvoiceJour         AVADAICustInvoiceJour;
    LogisticsPostalAddress  AVADAILogisticsPostalAddress;

    select InvoicePostalAddress from AVADAICustInvoiceJour where AVADAICustInvoiceJour.recid        == this.JournalRecId
            join Street from AVADAILogisticsPostalAddress where AVADAILogisticsPostalAddress.recid  == AVADAICustInvoiceJour.DeliveryPostalAddress;
    return AVADAILogisticsPostalAddress.Street;
}

